   "focus": "Part 3 is a text with <b>8 gaps</b>; you change the word in CAPITALS so that it fits. At C1 most answers need <b>more than one change</b>: a prefix <b>and</b> a suffix (<i>COMPARE → incomparably</i>), a negative form (<i>PLACE → irreplaceable</i>), an internal change (<i>DEEP → depth</i>) or a compound (<i>BREAK → outbreak</i>). Practise the modules one by one, then do the mixed tests.",
