      "a": 2,
      "w": "The falcon shows what the “fixed number” rule is for: a flock that stays “coherent” can pass a turn through its whole body faster than the predator can attack. So cohesion is a survival advantage (C). One bird notices the falcon first, but there is no permanent leader (A), and nothing is said about random triggers (D)."
