    "id": "c1-p5-12",
    "title": "Should We Bring Them Back?",
    "text": "The idea has a seductive simplicity. Somewhere in the permafrost of Siberia lie the preserved remains of woolly mammoths, and in their cells, damaged but recoverable, are fragments of genetic code. Splice enough of it into the cells of a living elephant, the argument runs, and a creature that vanished some four thousand years ago might walk the tundra again. Companies and university laboratories have attracted considerable funding on the strength of this promise, and the phrase \"de-extinction\" has passed from science fiction into the vocabulary of serious grant applications.\n\nYet the biologists who work on the problem are quick to point out that what they would create is not a mammoth in any strict sense. Dr Lucía Ferrandis, who has spent a decade studying ancient DNA, describes the project as \"a cold-resistant elephant with a mammoth's coat and a few of its habits\". The genomes of the two animals differ in some millions of places, and nobody knows which differences matter. The best that can be hoped for, she says, is a proxy: an animal that looks and behaves enough like the original to fulfil its role in the ecosystem. Whether a proxy deserves the name of the original is, in her view, a philosophical question rather than a scientific one, and she is impatient with those who treat it as the central issue.\n\nAdvocates make a more practical case. Mammoths, they argue, kept the northern grasslands open by trampling snow, knocking down trees and fertilising the soil; without them the tundra has become mossy and insulated, and the permafrost beneath it is thawing, releasing carbon. Restoring a large grazer might therefore slow the process. It is an appealing chain of reasoning, but Ferrandis is cautious. \"Each link is plausible,\" she says, \"and the chain as a whole is untested. We would be conducting research on a scale that cannot be undone, in an ecosystem we only partly understand.\" A herd of a few dozen animals, she points out, could hardly be expected to alter a landscape the size of a continent, and the experiments needed to prove otherwise would take generations.\n\nThe ethical objections are of a different order. The first mammoth-like calf would have to be carried by an elephant, an animal with a pregnancy of twenty-two months and an intensely social life, and early attempts would almost certainly fail, with miscarriages and malformed offspring. Even success would produce a lonely creature, raised without the herd from which a young elephant learns nearly everything it needs to know. Critics ask what right we have to create an animal for a purpose that is, in the last resort, as much about prestige as about science. Supporters reply that every medical advance has demanded its sacrifices, but the comparison is an uneasy one: a patient can consent to a trial, and an elephant cannot.\n\nThere is also the matter of priorities. Conservation budgets are modest, and a cynic might suspect that the glamour of the mammoth will draw funding away from the unglamorous work of protecting living species. Ferrandis shares the worry, though she is careful not to overstate it. The same technologies, she notes, are already being used on endangered animals: genetic material from preserved cells has given a shot in the arm to a programme for the black-footed ferret, adding diversity to a population descended from just seven individuals. If de-extinction research delivers tools of that kind, she says, it will have justified itself, whatever happens to the mammoth. But she warns of a subtler danger: the belief that extinction can be reversed may weaken the urgency of preventing it. \"If the public thinks we can bring things back,\" she says, \"that will pull the rug out from under every argument for protecting them now.\"\n\nWhere, then, does this leave the project? Ferrandis refuses to dismiss it, and refuses equally to cheer it on. For better or worse, she says, the technology exists and will be developed by someone, so the sensible course is to insist on openness: published methods, independent oversight and an honest account of what can and cannot be delivered. At present much of the work proceeds out of sight, inside private companies with investors to satisfy and announcements to time. \"The real danger is not that scientists will bring a mammoth back,\" she says. \"It is that nobody will be able to say, with a straight face, what we have brought back.\"",
