    "id": "c1-p5-13",
    "title": "The Slow Rise",
    "text": "The baker's alarm goes off at half past two, and by three o'clock Marguerite Oyelaran is standing in a warm, flour-dusted kitchen, scoring the surface of the first loaves of the day with a razor blade. It looks effortless: one confident curve, a flick of the wrist, and the dough opens as if it had been waiting to. In fact, she tells me, it took her the best part of three years to produce a loaf she would have been prepared to sell. \"People think bread is a recipe,\" she says. \"It isn't. It's a conversation with something alive, and you only learn the language by getting it wrong.\"\n\nThat something alive is a starter: a mixture of flour and water in which wild yeasts and bacteria, present on the grain and in the air, have been allowed to multiply. Until the nineteenth century, almost all bread was raised in this way; the commercial yeast that replaced it was faster, more predictable and, to the industrial bakeries that adopted it, a godsend. A sourdough loaf, by contrast, can take two days from start to finish, and its behaviour depends on the temperature of the room, the age of the starter and even the particular flour that happens to be used. The process is, technically, a matter of chemistry. In practice, it is closer to husbandry.\n\nIt is this unpredictability, paradoxically, that has made sourdough so fashionable. When the pandemic confined millions of people to their homes, shops ran out of flour and social media filled with photographs of lopsided loaves. Psychologists who study hobbies suggest that the appeal lay less in the bread than in the experience of effortful, absorbing work with a visible result: an antidote, perhaps, to days that otherwise dissolved into screens. Marguerite is sceptical. \"First and foremost, people were bored and anxious,\" she says. \"Bread gave them something to do with their hands. I'm not saying that's a bad thing, but let's not pretend it was a revolution in taste.\"\n\nHer scepticism extends to the economics of her trade. She opened her bakery with a modest sum borrowed from an uncle and a loan that took her months to arrange, and she insists that the romantic picture of the artisan baker conceals a brutal arithmetic. Flour prices swing wildly, ovens consume enormous quantities of energy, and a loaf that takes two days to make cannot be sold at the price of one that takes two hours. \"You need money to make money,\" she says, with a shrug, \"and nobody tells you that in the first year you will earn less than the people who work for you.\" Several bakeries in the area have closed since she opened, and she suspects that others have survived only because their owners have second incomes.\n\nWhat, then, keeps her going? Part of the answer, she suggests, lies in the rhythm of the work itself. A baker cannot rush; the dough will not be hurried, and any attempt to force it produces a flat, dense loaf that is, in her words, \"a lesson in humility\". There is a decision to be made at every stage — when to fold, when to rest, when to shape — and none of them can be made by consulting a timetable. They require attention to smell, to texture, to the way the surface of the dough responds to a finger. The skill, in other words, is not a store of facts but a trained perception, and it is acquired only through repetition. She compares it to learning a musical instrument: the early months are all clumsiness and self-doubt, and then, one morning, the hands simply know.\n\nHer apprentice, a nineteen-year-old called Tobias, is currently in the clumsy stage. He arrived expecting to learn recipes and has discovered that the recipes matter least. \"On my first day I asked her how long to leave the dough,\" he laughs. \"She said, 'Until it's ready.' I thought she was joking.\" Marguerite is unapologetic. She would rather he made a hundred poor loaves in his first year and understood why each one failed than mastered a formula he could not adapt. \"If I handed him a rulebook, I'd be doing him no favours. The day the flour changes, or the weather turns, the rulebook is useless — and then he'd be as lost as the customers who think they can buy all this in a kit.\" Yet she expects him to pull his weight from the second week, scrubbing trays and shaping rolls, and by her own account he has done so without complaint.",
