      "n": 1,
      "s": "has a different view from the others about whether social media actually causes lower self-esteem?",
      "a": "A",
      "w": "<b>A</b> doubts the link, calling the studies <i>mostly correlational</i> and suggesting any harm is indirect. B blames hostile comments, C calls comparison <i>a causal one</i>, and D describes <i>the dip in self-worth</i> that feeds produce."
