    "id": "c1-p6-05",
    "title": "Cities Without Cars",
    "intro": "You are going to read four extracts from articles in which writers discuss banning cars from city centres.",
    "stem": "Which writer",
    "sections": [
     {
      "l": "A",
      "h": "Writer A — Dr Hana Petrova, urban planner",
      "t": "The most persuasive argument for clearing cars from a city centre has little to do with carbon dioxide, important though that is. It is about what a street is for. Once the road is no longer a conduit for traffic, it becomes somewhere to sit, to play and to meet, and the shops along it do better, not worse: counts of pedestrians in cleared streets consistently rise, and walkers tend to spend more over a month than drivers. I would, however, resist exemptions, however sympathetic the case; every permit issued is a loophole that weakens the principle, and in my experience the number of 'essential' vehicles swells with each review. Where I would be patient is in timing. Traders, residents and bus operators need years to adapt, and a scheme introduced gradually, with alternatives such as cycle lanes and tram routes in place beforehand, will win consent that a sudden decree never could. The point of no return should be passed because people want it, not because they have been ordered to."
     },
     {
      "l": "B",
      "h": "Writer B — Mr Louis Mercier, architect",
      "t": "I have designed squares in a dozen cities, and nothing transforms a place like removing its cars. The gains in air quality are welcome, but they are not the point; what a car-free centre gives back is room, the generosity of space in which people linger and bargain and argue. Shopkeepers invariably predict ruin, and invariably their takings rise once crowds can stroll without being flattened. Nor am I moved by calls for carve-outs, which turn a clean idea into a bureaucratic maze. As for timing, I part company with those urging gradual change. Pilot schemes and consultations draw the process out until opponents have organised, whereas a city that acts on a single date finds that the shock subsides within weeks and that nobody wants the traffic back. Peeling a plaster off slowly merely prolongs the sting, and a bold decision, firmly carried through, is kinder to everyone than years of anxious dithering."
     },
     {
      "l": "C",
      "h": "Writer C — Ms Beatriz Salgado, spokesperson for a retail trade association",
      "t": "As spokesperson for a trade association representing independent retailers, I am used to being caricatured as the enemy of progress. In fact, many of our members welcome cleaner air; councils usually justify bans by pointing to lower carbon dioxide and fewer exhaust fumes, and that is a case I accept. What our members fear, with good reason, is the loss of customers who cannot or will not arrive on foot: the shopper carrying heavy goods, the grandmother who lives out of town, the plumber unloading tools. Surveys from some cities are cited to show footfall rising, but they count passers-by, not paying customers, and several shops I know have seen takings slump after pedestrianisation. A ban that ignores such realities is blunt. Residents with disabilities, the critically ill, elderly people and businesses that rely on deliveries should be allowed access under a permit system, however untidy that may look on a planner's map. Equally, no sensible council would introduce restrictions overnight; a phased approach, starting with weekends, gives trade time to recover and everyone a chance to iron out problems."
     },
     {
      "l": "D",
      "h": "Writer D — Prof Oliver Banks, transport economist",
      "t": "Economists tend to ask what a policy costs and who pays, and on that score central-area car bans are rather easier to defend than their critics claim. Congestion wastes millions of working hours a year; clearing the streets frees them, and the commercial benefits of a more pleasant centre flow back through higher property values and trade. I advised a central bank for years and am wary of rosy forecasts, yet I accept that vendors fear losses, and the evidence suggests that, over time, cities that have restricted traffic see stable or growing takings. A well-designed scheme must, however, bear in mind those for whom walking is no option. Disabled residents and older people should keep a right of access, and I would confine deliveries to early-morning windows. Doing so costs little and wins public support, which matters more than purity. Likewise, I would introduce the restrictions in stages, with the first zones acting as an experiment from which the later ones learn; the process is slower, but the mistakes are cheaper."
     }
    ],
