      "n": 1,
      "s": "has a different view from the others about whether streaming has widened the range of music people discover?",
      "a": "D",
      "w": "A, B and C all say that the services keep people in a loop of familiar suggestions. Only D reports that streaming introduced customers to music <i>\"they would never have met in our racks\"</i>."
