    "w": {
     "1": "Before: <i>begins, improbably, with a dead tree</i>; the gap describes <i>The tree in question</i>. After: <i>His curiosity only deepened</i> refers to Pryce's reaction to the unknown, unusual apple (<i>unlike anything he had tasted</i>).",
     "2": "Before: <i>a fruit without a name... determined to give this one both</i> (name and history); <i>Doing so</i> refers to giving it a name and history, and the gap tells how (four years, a catalogue). After: <i>Identification</i> picks up the matching of the variety.",
     "3": "Before: <i>a good deal of criticism</i>; <i>The cause was land</i> explains why people criticised him, and <i>came under... criticism</i> repeats the idea. After: <i>he did not hold a grudge</i> shows his reaction to those critics.",
     "4": "Before: <i>The man ate three in silence, and withdrew his objection</i>; <i>News of the conversion</i> refers to the critic changing his mind. After: <i>turned the supermarket down</i> follows the <i>supermarket buyer</i> in the gap.",
     "5": "Before: <i>something that surprised even his friends</i>; <i>He gave the trees away</i> says what it was. After: <i>This conviction</i> refers to the belief that the variety should be shared freely.",
     "6": "Before: <i>Whether the scheme will actually work is another matter</i>; <i>The omens are encouraging</i> answers it with evidence. After: <i>Pryce himself refuses to declare victory</i> contrasts with the encouraging results."
    },
