    "w": {
     "1": "Before: <i>The reason was a retirement party</i>; the gap explains it (<i>My colleagues... buy me a handsome wooden set</i>). After: <i>In the end it was boredom that made me open the box</i> refers to the set (<i>box</i>) left on the shelf.",
     "2": "Before: <i>looked for somebody else to lose to</i>; the gap describes the club and <i>He beat me in nineteen moves</i>. After: <i>That first defeat</i> refers to that game, and <i>the man in the cardigan</i> was introduced in the gap.",
     "3": "Before: <i>a way to learn from each one</i>; <i>This took the form of a notebook</i> says what the way was. After: <i>The notebook</i> is mentioned again, and <i>was not flattering</i> comments on what the exercise revealed.",
     "4": "Before: <i>do not yield to good resolutions</i>; <i>What eventually did</i> picks up the verb \"yield\", answering what finally changed the habits. After: <i>I did not win, as it happens</i> follows <i>the third</i> game and the complicated position.",
     "5": "Before: <i>what accounted for it</i>; <i>Part of the answer</i> responds to that sentence. After: <i>It is also why</i> continues the explanation of responsibility with a further consequence (chess and age).",
     "6": "Before: <i>The younger members of the club... seem to agree</i>; <i>They treat me as a peer</i> refers to the younger members. After: <i>the same boy</i> refers to the fifteen-year-old of the gap paragraph."
    },
