    "w": {
     "1": "<b>Before:</b> she <i>never expected to spend her thirties</i> in a coal-industry building. G explains how she came to it (<i>The idea had arrived almost by accident</i>) and mentions the town's <i>disused plant</i>. <b>After:</b> <i>The council, understandably, was wary</i> follows from that. A is about a different plant and a demolition.",
     "2": "<b>Before:</b> a <i>three-year lease</i>. C opens <i>Three years proved a tight schedule</i> and ends with <i>every variable ... is yours to get wrong</i>. <b>After:</b> Okafor <i>suggested logging everything</i>, a response to those variables.",
     "3": "<b>Before:</b> the pair now understand their trays. E says who would buy the produce and ends with customers who <i>ask awkward questions</i>, which is exactly what <b>After:</b> <i>The questions, as it turned out</i> continues.",
     "4": "<b>Before:</b> <i>the sums looked very different once transport was counted</i>. D opens <i>Transport, in fact</i> and finishes with the council's use of the project, so that <b>After:</b> <i>Other towns have noticed</i> follows naturally.",
     "5": "<b>Before:</b> the limits of indoor farming (<i>the crops on which most of humanity depends</i>). F begins <i>Her own plans are more modest than the headlines suggest</i> and mentions grandfathers who worked <i>in the very hall</i>. <b>After:</b> <i>The irony</i> refers to exactly that link with the town's industrial past.",
     "6": "<b>Before:</b> the <i>boiler crew</i> photograph. B begins <i>She does admit to one fear</i> and ends with the farm as a <i>classroom</i> and <i>laboratory</i>. <b>After:</b> <i>the place was full of children</i> shows that role."
    },
