    "w": {
     "1": "<b>Before:</b> she has turned down offers <i>every time</i>. B describes <i>the first approach</i> and ends with her question about <i>the starter</i>. <b>After:</b> <i>It was not a rhetorical question</i> refers directly to that question. G is a rival's story and has no such link.",
     "2": "<b>Before:</b> the buyer and the question about the starter. E opens <i>The meeting ended politely, but a second, subtler offer followed</i> and ends with <i>a contract of sixty pages</i>. <b>After:</b> <i>Brandt read all sixty pages</i> repeats that number.",
     "3": "<b>Before:</b> <i>all or nothing</i> and the decision about the fund. C starts <i>She turned down the contract</i> and ends with Brandt wondering about her staff's futures. <b>After:</b> <i>The solution, when it came, was Elena's own</i> answers that worry.",
     "4": "<b>Before:</b> four apprentices have opened bakeries <i>up and down the coast</i>. A begins with <i>these offspring</i>, which are those bakeries, and ends with her conviction that the town <i>has gained far more</i> from them <i>than it would have from any expansion</i>. <b>After:</b> <i>Not everyone agrees</i> introduces a counter-argument to her view.",
     "5": "<b>Before:</b> the argument about towns and bakeries. D begins <i>The economics are, she concedes, unforgiving</i> and ends with <i>one figure only</i>. <b>After:</b> <i>That single number</i> refers to the figure, loaves unsold at closing.",
     "6": "<b>Before:</b> the recipe changes. F says <i>Nothing about her own routine has changed</i> and ends with <i>the queue</i>. <b>After:</b> <i>Last winter, as the queue stretched round the corner</i> picks up the queue."
    },
