    "w": {
     "1": "<b>Before:</b> the bus driver and <i>The label was the problem</i>. F begins with Dlamini's shock at the error and ends with <i>the gap between those who write labels and those who read them</i>. <b>After:</b> <i>The writers, in her experience</i> picks up that gap.",
     "2": "<b>Before:</b> volunteers <i>explain what each one meant</i>. A reports the results of that experiment and the four mistakes. <b>After:</b> <i>Armed with the list</i> refers to the list of mistakes.",
     "3": "<b>Before:</b> clearer wording, units written out and times of day. D shows another step, <i>Dosage presented a more stubborn problem</i>, and ends with the error rate falling. <b>After:</b> <i>Numbers alone, though, convinced the industry rather less</i> responds to those figures.",
     "4": "<b>Before:</b> adoption by hospitals. G opens <i>Dlamini is wary of this success</i> and ends by studying how to <i>head off</i> panic. <b>After:</b> <i>Her solution is a kind of triage</i> answers that problem.",
     "5": "<b>Before:</b> regulators and drug companies who fear <i>concealment</i>. B opens <i>Behind the caution</i> and explains the dilemma. <b>After:</b> <i>That scepticism</i> refers to her treating every rule as a <i>hypothesis</i>.",
     "6": "<b>Before:</b> teaching at a pharmacy school. E starts <i>Her fiercest critics</i> and ends with the line on the labels. <b>After:</b> <i>She has not yet discovered whether the line works</i> refers directly to it. C, the extra, is a history of labels and does not link with the paragraphs around any gap."
    },
