     "1": "Before: <i>a project</i> involving volunteers. G begins <i>The project is a forecasting tournament</i> and introduces the scoring. After: <i>The scoring</i> refers to the percentages and points that G describes.",
     "2": "Before: <i>a single habit</i>. D says <i>The habit in question</i> and names it (revising forecasts). After: <i>Such flexibility</i> picks up changing numbers <i>without embarrassment</i>.",
     "3": "Before: <i>wrongness</i> in the tournament versus workplaces. B says <i>Not everyone is convinced</i> and gives the critics' objection (the real world). After: <i>At least business leaders</i> gives a positive example that answers the critics.",
     "4": "Before: firms in business are starting to use the method. E says <i>Public life has been slower to adapt</i>, a contrast. After: <i>Part of the difficulty</i> is about why public statements stay overconfident (unqualified claims).",
     "5": "Before: the unqualified claim is a warning sign. F begins <i>He is wary, though</i> and says the aim is not perfection. After: <i>What the winners do share</i> contrasts with that: not perfection, but humility.",
     "6": "Before: the top forecasters list their worst misses. A moves to <i>Bashir's own record</i> and the notebook page on the wall. After: <i>that the page is a joke</i> and <i>the handwriting is mine</i> refer to the framed notebook page. Paragraph C has no link to a gap."
